// Gelasio (OFL, Georgia metric-compatible) — editorial template.
// LATIN-SUBSET (fontTools, ranges match arimo-fonts.ts), base64-bundled so the
// CV PDF renderer has NO runtime network fetch. Raw .ttf sources are gitignored;
// these base64 modules are the committed source the renderer loads.
//
// Per-file (subset):
//   GELASIO_REGULAR: 68.0 KB
//   GELASIO_BOLD: 68.0 KB
//   GELASIO_ITALIC: 69.1 KB
//   GELASIO_BOLDITALIC: 69.1 KB

const decode = (b64: string): Uint8Array =>
  Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

export const GELASIO_REGULAR: Uint8Array = decode(
  "",
);
export const GELASIO_BOLD: Uint8Array = decode(
  "",
);
export const GELASIO_ITALIC: Uint8Array = decode(
  "",
);
export const GELASIO_BOLDITALIC: Uint8Array = decode(
  "",
);
